import torch
import torchaudio
from torch.utils.data import Dataset, DataLoader

class SpeechEmotionDataset(Dataset):
    def __init__(self, file_paths, labels, target_sr=16000, max_seconds=3.0):
        self.file_paths = file_paths
        self.labels = labels
        self.target_sr = target_sr
        self.max_len = int(target_sr * max_seconds)

    def __len__(self):
        return len(self.file_paths)

    def __getitem__(self, idx):
        wav, sr = torchaudio.load(self.file_paths[idx])
        if sr != self.target_sr:
            wav = torchaudio.transforms.Resample(sr, self.target_sr)(wav)
        wav = wav.mean(dim=0) # Mono
        if wav.shape[0] < self.max_len:
            wav = torch.nn.functional.pad(wav, (0, self.max_len - wav.shape[0]))
        else:
            wav = wav[:self.max_len]
        return {"input_values": wav, "labels": torch.tensor(self.labels[idx], dtype=torch.long)}

